 const label=m.battery==null?'Bateria indisponível':`${m.battery}%${m.charging?' · A carregar':''}${freshness==='stale'?' · Última leitura conhecida':''}${!demo&&m.battery_updated?' · '+new Date(m.battery_updated).toLocaleString('pt-PT'):''}`;
