 <div className="map-content" style={{transform:`scale(${zoom})`}}>{members.slice(0,4).map((m,i)=>{const p=positions[m.id]||[[56,48],[30,65],[74,28],[60,74]][i];return <button key={m.id} className={`map-marker ${selected===m.id?'selected':''}`} style={{left:p[0]+'%',top:p[1]+'%'}} onClick={()=>onSelect(m.id)}><Avatar m={m}/><span>{short(m.name)}{m.speed>0&&<small>{m.speed} km/h</small>}</span></button>})}<span className="place-label school"><Home size={13}/> Escola</span><span className="place-label house"><Home size={13}/> Casa</span></div>
